"""Принятая логика разгрузки. Заводские клеммы и уставки ещё не назначены.

Отключаемые цепи имеют собственную дифзащиту. Их выходные N не объединяются.
Кондиционеры останавливаются разрешённым изготовителем входом управления.
"""

# Группа: исполнитель, очередность снятия, способ, возврат.
CONTROLLED = {
    15: ("KM1", 1, "силовой контакт L", "вручную кнопкой SB1 после выключения фена"),
    19: ("KM2", 2, "силовой контакт L", "автоматически с задержкой и запасом мощности"),
    20: ("KA3", 3, "сухой контакт разрешения работы", "по паспорту кондиционера, с защитой от частых пусков"),
    21: ("KA4", 4, "сухой контакт разрешения работы", "по паспорту кондиционера, с защитой от частых пусков"),
    9: ("KM5", 5, "силовой контакт L", "вручную кнопкой SB5 после проверки приборов"),
}


def priority_rows():
    names = {15: "Розетки санузлов и полотенцесушители", 19: "Тёплые полы",
             20: "Кондиционер спальни", 21: "Кондиционер гостиной",
             9: "Вся кухонная розеточная линия, СВЧ и вытяжка"}
    return [[str(order), f"QF{g} · {names[g]}", device, method, restore]
            for g, (device, order, method, restore) in CONTROLLED.items()]


